using System;
using System.Web;

namespace InformationWeb.Pages.Error404
{
    public static class ErrorHandler
    {
        private const string NotFoundPagePath = "~/Pages/404/NotFound.aspx";

        public static bool IsNotFoundPageRequest(HttpRequest request)
        {
            if (request == null)
                return false;

            string path = request.Path.ToLower();
            return path.IndexOf("/pages/404/notfound.aspx") >= 0;
        }

        public static void RedirectToNotFound(HttpContext context)
        {
            if (context == null)
                return;

            if (IsNotFoundPageRequest(context.Request))
                return;

            context.Server.ClearError();
            context.Response.Clear();
            context.Response.TrySkipIisCustomErrors = true;
            context.Response.StatusCode = 404;
            context.Response.StatusDescription = "Not Found";
            context.Server.Transfer(NotFoundPagePath, false);
        }

        public static void SetNotFoundResponse(HttpResponse response)
        {
            if (response == null)
                return;

            response.TrySkipIisCustomErrors = true;
            response.StatusCode = 404;
            response.StatusDescription = "Not Found";
        }
    }
}

.not-found-wrap {
    min-height: 420px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 40px 20px;
}

.not-found-box {
    max-width: 640px;
    width: 100%;
    text-align: center;
    background: #ffffff;
    border: 1px solid #16218522;
    border-radius: 16px;
    box-shadow: 0 8px 24px rgba(22, 33, 133, 0.08);
    padding: 48px 32px;
}

.not-found-code {
    font-size: 96px;
    line-height: 1;
    font-weight: 700;
    color: #162185;
    margin-bottom: 8px;
}

.not-found-title {
    font-size: 28px;
    font-weight: 700;
    color: #162185;
    margin-bottom: 16px;
}

.not-found-message {
    font-size: 16px;
    line-height: 1.7;
    color: #4a5568;
    margin-bottom: 28px;
}

.not-found-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    justify-content: center;
}

.not-found-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 160px;
    padding: 10px 20px;
    border-radius: 999px;
    font-size: 14px;
    font-weight: 600;
    text-decoration: none;
    transition: all 0.2s ease;
}

.not-found-btn-primary {
    background: #162185;
    border: 1px solid #162185;
    color: #ffffff;
}

.not-found-btn-primary:hover {
    background: #0f1760;
    border-color: #0f1760;
    color: #ffffff;
}

.not-found-btn-secondary {
    background: #ffffff;
    border: 1px solid #ff5e5e;
    color: #ff5e5e;
}

.not-found-btn-secondary:hover {
    background: #fff5f5;
    color: #e04b4b;
}

.not-found-icon {
    font-size: 56px;
    color: #ff5e5e;
    margin-bottom: 12px;
}

@media (max-width: 767px) {
    .not-found-code {
        font-size: 72px;
    }

    .not-found-title {
        font-size: 22px;
    }

    .not-found-box {
        padding: 32px 20px;
    }
}

